func (GRPCDatabasePlugin) GRPCClient(doneCtx context.Context, _ *plugin.GRPCBroker, c *grpc.ClientConn) (interface{}, error) {
	client := gRPCClient{
		client:        proto.NewDatabaseClient(c),
		versionClient: logical.NewPluginVersionClient(c),
		doneCtx:       doneCtx,
	}
	return client, nil
}

